function validate(input) {
  const [{ Users = [] }] = input;
  const ids = new Set();
  for (const [id, name] of Users) {
    if (id === null) return 'Every user needs a user_id.';
    if (ids.has(id)) return `user_id ${id} appears twice in Users.`;
    ids.add(id);
    if (name === null || !/^[A-Za-z]{1,40}$/.test(name)) return `The name of user ${id} must be 1 to 40 English letters.`;
  }
  return null;
}

