function generate(rand, size) {
  const bases = ['alice', 'bob', 'x', 'jo', 'charlie', 'mary', 'z', 'ann', 'leetcode'];
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  // Each letter's case is drawn at random, so names arrive all lower, all upper, mixed, or already correct.
  const scramble = word => [...word].map(c => (rand() < 0.5 ? c.toUpperCase() : c)).join('');
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const ids = [];
  for (let id = 1; ids.length < count; id++) if (size !== 'small' || rand() < 0.7) ids.push(id);
  // Shuffle so the stored order differs from the user_id order the output needs.
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Users = ids.map(id => {
    let word;
    if (size === 'small') word = bases[Math.floor(rand() * bases.length)];
    else { const length = 1 + Math.floor(rand() * 12); word = ''; for (let k = 0; k < length; k++) word += letters[Math.floor(rand() * 26)]; }
    return [id, scramble(word)];
  });
  return [{ Users }];
}
